  "write:piechart": { id: "y2WNnp5nZ54", title: "Cách làm bài biểu đồ tròn", channel: "The Forum", note: "Dạy bằng tiếng Việt: chiến thuật + phân tích mẫu cho biểu đồ tròn.", start: 0, end: 349 },
  "zhSpeak:chaohoi3": { id: "gI4NInzzjOs", title: "Chào hỏi/giới thiệu trong thương mại (HSK3+)", channel: "luyendich tiengTrung", note: "Chào hỏi/giới thiệu trong thương mại: nội dung thương mại/ngoại thương đúng phạm vi HSK3+. CỜ: tiêu đề không ghi rõ HSK3+; chỉ nghe đầu video. Bài luyện nghe/nói/đọc tiếng Trung — nghe tiếng Trung là đúng bản chất bài, không phải video dạy sai ngôn ngữ.", start: 0, end: 315 },
