  "readEp:4": { id: "LwIDnQ1Xsd4", title: "Tên màu, phát âm và thành ngữ về màu", channel: "KISS English Center", note: "Dạy bằng tiếng Việt: tên màu/phát âm/thành ngữ về màu, không dạy tâm lý màu sắc ảnh hưởng con người. Khớp ở mức chủ đề chung.", start: 0, end: 574 },
  "readEp:20": {id: "Y-IcsB5Qhjs", title: "Thiên nhiên", channel: "Tran Tran", note: "Dạy bằng tiếng Việt (dạng song ngữ thẻ từ: từ tiếng Anh kèm nghĩa tiếng Việt): thiên nhiên nói chung, khớp chủ đề chung cây giao tiếp. CỜ: không riêng cây giao tiếp; chỉ nghe đầu; kênh nhỏ (391 đăng ký).", start: 0, end: 243},
  "readEp:114": {id: "I4r6Iu9e2s8", title: "Công nghệ và phát minh", channel: "Uspeak English", note: "Dạy bằng tiếng Việt: công nghệ/phát minh nói chung, khớp chủ đề chung thuật toán định hình cách đọc. CỜ: không riêng thuật toán; bằng chứng tiếng Việt ở quanh giây 64.", start: 0, end: 539},
  "readEp:30": {id: "zQuIjnzk42c", title: "Từ vựng nghề nghiệp và công việc", channel: "KISS English Center", note: "Dạy bằng tiếng Việt: từ vựng nghề nghiệp/công việc nói chung, khớp chủ đề chung chính sách làm việc linh hoạt. CỜ: không riêng chính sách làm việc linh hoạt; chỉ nghe đầu. Dùng chung video với speakEp:110.", start: 0, end: 2208},
  "readEp:5": { id: "HEFzKmhQGpg", title: "Từ vựng chủ đề cà phê", channel: "SmartEnglish Channel", note: "Dạy bằng tiếng Việt: từ vựng cà phê chung, không riêng lợi ích cà phê/caffeine. Khớp ở mức chủ đề chung.", start: 0, end: 733 },
