// ============================================================
//  DOT v204 16/11/2026 — xoay dap an trac nghiem luyen tap theo ma noi dung cau.
//  Ly do: dap an dung don ve mot vi tri (ngu phap ZH 93% o A, TP 85% o A; entry TP 16/16
//  o A; doc/nghe TP 191/193 va 169/169 o A; ngu phap EN 621/443/190/6; doc EN 239/406 o A,
//  nghe EN 279/464 o A) — nguoi hoc doan duoc dap an theo vi tri thay vi hoc noi dung.
//  Cach lam: giong DOT 3/3b (30/10) da xoay mock + ZH nghe/doc/viet luc nap trang — chi doi
//  vi tri lua chon, dap an dung (noi dung cau) khong doi. Xoay theo bam FNV-1a cua
//  (cau hoi + dap an dung) nen on dinh moi lan nap va khong tuong quan voi chi so
//  (bai hoc DOT 3b: xoay theo chi so van don dap an khi dap an cu tuong quan voi chi so).
//  Khong xoay: cau khong phai trac nghiem (khong co o/options, hoac type khac MC o doc/nghe EN),
//  lua chon meta ("tat ca..."/"khong co..."/"ca A va B"), lua chon trung nhau,
//  lua chon toan so/nam da xep thu tu, cau ghim test_v145 (ZH_PH_STEPS[0] cau "r"),
//  va cac mang DOT 3/3b da xoay (ZH_READING, ZH_LISTENING, ZH_WRITE, TC_MOCK*, TP_MOCK*).
// ============================================================
(function () {
  function rot(q, shift) {
    /* SUA v204b (16/11, phat hien nho suite: u7 W2 45 cau): cau co CA 2 truong
       o va options (155 cau Doc EN, 2 truong giong het nhau) phai xoay CA 2
       cung mot shift — ban dau chi xoay o, options giu nguyen nhung a da doi
       nen options[a] tro thanh dap an SAI (why noi "Chín tuổi" nhung a chi
       "Mười tuổi"). Neu 2 truong lech do dai thi BO QUA (khong xoay) de
       khong lam lech dap an. */
    var keys = [];
    if (Array.isArray(q.o)) keys.push("o");
    if (Array.isArray(q.options)) keys.push("options");
    if (!keys.length) return;
    var o = q[keys[0]]; if (!o || o.length < 2) return;
    if (keys.length > 1 && q[keys[1]].length !== o.length) return;
    var s = ((shift % o.length) + o.length) % o.length; if (!s) return;
    keys.forEach(function (k) { q[k] = q[k].slice(s).concat(q[k].slice(0, s)); });
    q.a = (q.a - s + o.length) % o.length;
  }
  function fnv(str) {
    var h = 0x811c9dc5;
    for (var i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
    return h >>> 0;
  }
  function norm(s) { return String(s == null ? "" : s).replace(/\s+/g, " ").trim().toLowerCase(); }
  var META = ["tất cả các đáp án trên", "all of the above", "không có đáp án nào đúng",
    "none of the above", "cả a và b", "both a and", "cả a và c", "cả b và c",
    "tất cả đều đúng", "tất cả đều sai"];
  function skipQ(q) {
    var opts = (q && (q.o || q.options)) || null;
    if (!q || !opts || opts.length < 2) return true;
    if (typeof q.a !== "number" || q.a < 0 || q.a >= opts.length) return true;
    if (q.type && q.type !== "MC") return true; // doc/nghe EN: chi xoay MC
    if ((q.q || "").indexOf("“r” trong pinyin") >= 0) return true; // ghim test_v145 B5
    var seen = {}, nums = true, i, j, n;
    for (i = 0; i < opts.length; i++) {
      n = norm(opts[i]);
      if (seen[n]) return true; seen[n] = 1;
      for (j = 0; j < META.length; j++) if (n.indexOf(META[j]) >= 0) return true;
      if (!/^\d+([.,]\d+)?$/.test(n)) nums = false;
    }
    if (nums) {
      var vals = opts.map(function (x) { return parseFloat(String(x).replace(",", ".")); });
      var asc = true, desc = true;
      for (i = 1; i < vals.length; i++) { if (vals[i] < vals[i - 1]) asc = false; if (vals[i] > vals[i - 1]) desc = false; }
      if (asc || desc) return true;
    }
    return false;
  }
  function rotList(list) {
    if (!list) return;
    for (var i = 0; i < list.length; i++) {
      var q = list[i];
      if (skipQ(q)) continue;
      var opts = q.o || q.options;
      rot(q, fnv((q.q || "") + "\u0000" + String(opts[q.a])));
    }
  }
  function rotSets(arr) {
    if (!arr) return;
    for (var i = 0; i < arr.length; i++) rotList(arr[i].quiz || arr[i].questions || arr[i].qs || []);
  }
  if (typeof CONTENT !== "undefined" && CONTENT) {
    rotSets(CONTENT.grammar); rotSets(CONTENT.reading); rotSets(CONTENT.listeningPlus);
    rotList(CONTENT.trial); rotList(CONTENT.zeroTest);
  }
  rotSets(typeof ZH_GRAMMAR !== "undefined" ? ZH_GRAMMAR : null);
  rotSets(typeof TC_GRAMMAR !== "undefined" ? TC_GRAMMAR : null);
  rotSets(typeof TP_GRAMMAR !== "undefined" ? TP_GRAMMAR : null);
  rotSets(typeof ZH_PH_STEPS !== "undefined" ? ZH_PH_STEPS : null);
  rotList(typeof ZH_ENTRY_QS !== "undefined" ? ZH_ENTRY_QS : null);
  rotSets(typeof TC_READ !== "undefined" ? TC_READ : null);
  rotSets(typeof TP_READ !== "undefined" ? TP_READ : null);
  rotSets(typeof TC_LISTEN !== "undefined" ? TC_LISTEN : null);
  rotSets(typeof TP_LISTEN !== "undefined" ? TP_LISTEN : null);
  /* DOT v206 16/11/2026 — V204-15: xoay readingMock (thi thu IELTS Doc).
     Ly do: 280 cau co 58,2% dap an dung o A; 215 cau 4 lua chon co 63,3% o A,
     0% o D (SC 24/24 o A; MC 94/140 o A) — nguoi hoc doan A la trung.
     Chi xoay cau 4 lua chon dang MC (MC/MSEND/SC/MATCH); KHONG xoay TFNG/YNNG
     (lua chon True/False/Not Given, Yes/No/Not Given co thu tu chuan cua IELTS).
     Cung luat skipQ nhu tren (trung lua chon, meta, so xep thu tu) + xoay CA 2
     truong o va options cung mot shift (bai hoc V204-6b); bam FNV-1a cua
     (cau hoi + dap an dung) nen on dinh moi lan nap. */
  function skipMockQ(q) {
    var opts = (q && (q.o || q.options)) || null;
    if (!q || !opts || opts.length !== 4) return true;
    if (typeof q.a !== "number" || q.a < 0 || q.a >= opts.length) return true;
    if (q.type && ["MC", "MSEND", "SC", "MATCH"].indexOf(q.type) < 0) return true;
    var seen = {}, nums = true, i, j, n;
    for (i = 0; i < opts.length; i++) {
      n = norm(opts[i]);
      if (seen[n]) return true; seen[n] = 1;
      for (j = 0; j < META.length; j++) if (n.indexOf(META[j]) >= 0) return true;
      if (!/^\d+([.,]\d+)?$/.test(n)) nums = false;
    }
    if (nums) {
      var vals = opts.map(function (x) { return parseFloat(String(x).replace(",", ".")); });
      var asc = true, desc = true;
      for (i = 1; i < vals.length; i++) { if (vals[i] < vals[i - 1]) asc = false; if (vals[i] > vals[i - 1]) desc = false; }
      if (asc || desc) return true;
    }
    return false;
  }
  if (typeof CONTENT !== "undefined" && CONTENT) {
    (CONTENT.readingMock || []).forEach(function (r) {
      (r.questions || []).forEach(function (q) {
        if (skipMockQ(q)) return;
        var opts = q.o || q.options;
        rot(q, fnv((q.q || "") + "\u0000" + String(opts[q.a])));
      });
    });
  }
})();

